def parse(tree):
    # nodes are numbered in the order they appear in the array; a child always gets a larger number than its parent
    if not tree:
        return [], [], []
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def serialize(root, val, left, right):
    out = []
    queue = [root]
    for u in queue:  # the list grows while we walk it
        if u == -1:
            out.append(-1)
        else:
            out.append(val[u])
            queue.append(left[u])
            queue.append(right[u])
    while out and out[-1] == -1:
        out.pop()
    return out


def build_balanced(a):
    # node i is a[i]; the root of every range lo..hi is the lower middle index
    n = len(a)
    left, right = [-1] * n, [-1] * n
    root = -1
    stack = [(0, n - 1, -1, 0)]
    while stack:
        lo, hi, parent, side = stack.pop()
        if lo > hi:
            continue
        m = (lo + hi) // 2
        if parent == -1:
            root = m
        elif side == 0:
            left[parent] = m
        else:
            right[parent] = m
        stack.append((lo, m - 1, m, 0))
        stack.append((m + 1, hi, m, 1))
    return serialize(root, a, left, right)


def inorder(tree):
    val, left, right = parse(tree)
    out, stack = [], []
    u = 0 if val else -1
    while stack or u != -1:
        while u != -1:
            stack.append(u)
            u = left[u]
        u = stack.pop()
        out.append(val[u])
        u = right[u]
    return out


def mergeBsts(a, b):
    x, y = inorder(a), inorder(b)
    merged = []
    i = j = 0
    while i < len(x) or j < len(y):
        if j == len(y) or (i < len(x) and x[i] <= y[j]):
            v = x[i]
            i += 1
        else:
            v = y[j]
            j += 1
        if not merged or merged[-1] != v:
            merged.append(v)
    return build_balanced(merged)
